import Foundation
import UIKit
import Display
import AsyncDisplayKit
import SwiftSignalKit
import TelegramCore
import TelegramPresentationData
import ItemListUI
import PresentationDataUtils
import AccountContext

// MATTERMOST: Settings → About Relay → Open Source Licenses (Phase 4A). Lists Telegram-iOS (GPL) and the
// third-party components bundled in the app with their license texts. The list is a resource generated by
// `tools/relay-licenses/generate.py` from the license files in the source tree (`RelayLicenses.json` in the app
// bundle, from `Telegram/Relay/RelayLicenses.json`).

/// One entry of `RelayLicenses.json`.
struct RelayLicenseComponent: Decodable, Equatable {
    /// Display name, e.g. "WebRTC".
    let name: String
    /// License name as far as it could be determined, e.g. "BSD-3-Clause" or "Not determined".
    let license: String
    /// Project homepage, if known.
    let url: String?
    /// The license/notice text(s) from the source tree (with the copyright lines), or an explanation.
    let text: String
}

private struct RelayLicensesFile: Decodable {
    let components: [RelayLicenseComponent]
}

/// The bundled list (empty if the resource is missing).
func loadRelayLicenseComponents() -> [RelayLicenseComponent] {
    guard let url = Bundle.main.url(forResource: "RelayLicenses", withExtension: "json"), let data = try? Data(contentsOf: url) else {
        return []
    }
    return (try? JSONDecoder().decode(RelayLicensesFile.self, from: data))?.components ?? []
}

private final class RelayLicensesArguments {
    let openTelegram: () -> Void
    let openComponent: (RelayLicenseComponent) -> Void

    init(openTelegram: @escaping () -> Void, openComponent: @escaping (RelayLicenseComponent) -> Void) {
        self.openTelegram = openTelegram
        self.openComponent = openComponent
    }
}

private enum RelayLicensesSection: Int32 {
    case relay
    case components
}

private enum RelayLicensesEntry: ItemListNodeEntry {
    case telegram(title: String, label: String)
    case telegramInfo(String)
    case componentsHeader(String)
    case component(index: Int32, component: RelayLicenseComponent)
    case componentsInfo(String)

    var section: ItemListSectionId {
        switch self {
        case .telegram, .telegramInfo:
            return RelayLicensesSection.relay.rawValue
        case .componentsHeader, .component, .componentsInfo:
            return RelayLicensesSection.components.rawValue
        }
    }

    var stableId: Int32 {
        switch self {
        case .telegram:
            return 0
        case .telegramInfo:
            return 1
        case .componentsHeader:
            return 2
        case let .component(index, _):
            return 100 + index
        case .componentsInfo:
            return Int32.max
        }
    }

    static func <(lhs: RelayLicensesEntry, rhs: RelayLicensesEntry) -> Bool {
        return lhs.stableId < rhs.stableId
    }

    static func ==(lhs: RelayLicensesEntry, rhs: RelayLicensesEntry) -> Bool {
        switch lhs {
        case let .telegram(title, label):
            if case .telegram(title, label) = rhs {
                return true
            }
            return false
        case let .telegramInfo(text):
            if case .telegramInfo(text) = rhs {
                return true
            }
            return false
        case let .componentsHeader(text):
            if case .componentsHeader(text) = rhs {
                return true
            }
            return false
        case let .component(index, component):
            if case .component(index, component) = rhs {
                return true
            }
            return false
        case let .componentsInfo(text):
            if case .componentsInfo(text) = rhs {
                return true
            }
            return false
        }
    }

    func item(presentationData: ItemListPresentationData, arguments: Any) -> ListViewItem {
        let arguments = arguments as! RelayLicensesArguments
        switch self {
        case let .telegram(title, label):
            return ItemListDisclosureItem(presentationData: presentationData, systemStyle: .glass, title: title, label: label, sectionId: self.section, style: .blocks, action: {
                arguments.openTelegram()
            })
        case let .telegramInfo(text):
            return ItemListTextItem(presentationData: presentationData, text: .plain(text), sectionId: self.section)
        case let .componentsHeader(text):
            return ItemListSectionHeaderItem(presentationData: presentationData, text: text, sectionId: self.section)
        case let .component(_, component):
            return ItemListDisclosureItem(presentationData: presentationData, systemStyle: .glass, title: component.name, label: component.license, sectionId: self.section, style: .blocks, action: {
                arguments.openComponent(component)
            })
        case let .componentsInfo(text):
            return ItemListTextItem(presentationData: presentationData, text: .plain(text), sectionId: self.section)
        }
    }
}

public func relayLicensesController(context: AccountContext) -> ViewController {
    var pushControllerImpl: ((ViewController) -> Void)?
    let components = loadRelayLicenseComponents()

    let arguments = RelayLicensesArguments(openTelegram: {
        let presentationData = context.sharedContext.currentPresentationData.with { $0 }
        let strings = presentationData.strings
        let text = strings.Relay_Licenses_TelegramText + "\n\n" + strings.Relay_Licenses_SourceText + "\n" + relaySourceCodeURL
        pushControllerImpl?(RelayLicenseTextController(presentationData: presentationData, title: "Telegram-iOS", text: text))
    }, openComponent: { component in
        let presentationData = context.sharedContext.currentPresentationData.with { $0 }
        var text = component.license
        if let url = component.url, !url.isEmpty {
            text += "\n" + url
        }
        text += "\n\n" + component.text
        pushControllerImpl?(RelayLicenseTextController(presentationData: presentationData, title: component.name, text: text))
    })

    let signal = context.sharedContext.presentationData
    |> map { presentationData -> (ItemListControllerState, (ItemListNodeState, Any)) in
        let strings = presentationData.strings
        var entries: [RelayLicensesEntry] = [
            .telegram(title: "Telegram-iOS", label: "GNU GPL"),
            .telegramInfo(strings.Relay_Licenses_TelegramInfo),
            .componentsHeader(strings.Relay_Licenses_ComponentsHeader.uppercased())
        ]
        for (index, component) in components.enumerated() {
            entries.append(.component(index: Int32(index), component: component))
        }
        entries.append(.componentsInfo(strings.Relay_Licenses_ComponentsInfo))
        let controllerState = ItemListControllerState(presentationData: ItemListPresentationData(presentationData), title: .text(strings.Relay_Licenses_Title), leftNavigationButton: nil, rightNavigationButton: nil, backNavigationButton: ItemListBackButton(title: strings.Common_Back))
        let listState = ItemListNodeState(presentationData: ItemListPresentationData(presentationData), entries: entries, style: .blocks)
        return (controllerState, (listState, arguments))
    }

    let controller = ItemListController(context: context, state: signal, tabBarItem: nil)
    pushControllerImpl = { [weak controller] c in
        (controller?.navigationController as? NavigationController)?.pushViewController(c)
    }
    return controller
}

/// A license text in a scrollable, selectable text view. License texts are long (up to ~30 KB), too long for
/// one list item's text node, so this uses `UITextView`, which lays out and draws only what is visible.
final class RelayLicenseTextController: ViewController {
    private let presentationData: PresentationData
    private let text: String
    private var textView: UITextView?

    init(presentationData: PresentationData, title: String, text: String) {
        self.presentationData = presentationData
        self.text = text
        super.init(navigationBarPresentationData: NavigationBarPresentationData(presentationData: presentationData, style: .glass))
        self.title = title
        self.statusBar.statusBarStyle = presentationData.theme.rootController.statusBarStyle.style
    }

    required init(coder aDecoder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    override func loadDisplayNode() {
        self.displayNode = ASDisplayNode()
        self.displayNode.backgroundColor = self.presentationData.theme.list.plainBackgroundColor

        let textView = UITextView()
        textView.isEditable = false
        textView.isSelectable = true
        textView.backgroundColor = .clear
        textView.font = UIFont.monospacedSystemFont(ofSize: 12.0, weight: .regular)
        textView.textColor = self.presentationData.theme.list.itemPrimaryTextColor
        textView.textContainerInset = UIEdgeInsets(top: 16.0, left: 12.0, bottom: 16.0, right: 12.0)
        textView.contentInsetAdjustmentBehavior = .never
        textView.alwaysBounceVertical = true
        textView.text = self.text
        self.displayNode.view.addSubview(textView)
        self.textView = textView

        self.displayNodeDidLoad()
    }

    override func containerLayoutUpdated(_ layout: ContainerViewLayout, transition: ContainedViewLayoutTransition) {
        super.containerLayoutUpdated(layout, transition: transition)

        let top = self.navigationLayout(layout: layout).navigationFrame.maxY
        if let textView = self.textView {
            transition.updateFrame(view: textView, frame: CGRect(x: layout.safeInsets.left, y: top, width: max(0.0, layout.size.width - layout.safeInsets.left - layout.safeInsets.right), height: max(0.0, layout.size.height - top)))
            textView.contentInset.bottom = layout.intrinsicInsets.bottom
            textView.verticalScrollIndicatorInsets.bottom = layout.intrinsicInsets.bottom
        }
    }
}
